async function pickServiceFzf(services) {
  const lines = services.map((s) => s.port ? `${s.name} :${s.port}` : s.name).join("\n");
  try {
    const result = await execa(
      "fzf",
      [
        "--height=40%",
        "--layout=reverse",
        "--border",
        "--prompt=devmux> ",
        "--header=Select service to start (Enter=start, Esc=cancel)"
      ],
      {
        input: lines,
        stdin: "pipe",
        stdout: "pipe",
        stderr: "inherit",
        reject: false
      }
    );
    if (result.exitCode !== 0 || !result.stdout.trim()) {
      return void 0;
    }
    const selected = result.stdout.trim().split(/\s/)[0];
    return selected || void 0;
  } catch {
    console.error("\u274C fzf not found. Install with: brew install fzf");
    return void 0;
  }
}
